class SimpleHashMap {
  constructor(size = 10) {
    this.buckets = new Array(size);
  }
  _hash(key) {
    let hash = 0;
    for (let i = 0; i < key.length; i++) {
      hash += key.charCodeAt(i);
    }
    return hash % this.buckets.length;
  }
  set(key, value) {
    const index = this._hash(key);
    this.buckets[index] = [key, value];
    console.log(`插入键 "${key}" 到索引 ${index}`);
  }
  get(key) {
    const index = this._hash(key);
    const entry = this.buckets[index];
    if (entry && entry[0] === key) {
      console.log(`找到键 "${key}" 在索引 ${index}，值为 ${entry[1]}`);
      return entry[1];
    }
    console.log(`键 "${key}" 未找到`);
    return undefined;
  }
}

const map = new SimpleHashMap();
map.set('name', 'Alice');
map.set('age', 25);
map.get('name');
map.get('age');
map.get('gender');

class ChainedHashMap {
  constructor(size = 5) {
    this.buckets = new Array(size).fill(null).map(() => []);
  }
  _hash(key) {
    let hash = 0;
    for (let i = 0; i < key.length; i++) {
      hash += key.charCodeAt(i);
    }
    return hash % this.buckets.length;
  }
  set(key, value) {
    const index = this._hash(key);
    const bucket = this.buckets[index];
    for (let entry of bucket) {
      if (entry[0] === key) {
        entry[1] = value;
        console.log(`更新键 "${key}" 在索引 ${index}`);
        return;
      }
    }
    bucket.push([key, value]);
    console.log(`插入键 "${key}" 到索引 ${index}，当前桶大小: ${bucket.length}`);
  }
  get(key) {
    const index = this._hash(key);
    const bucket = this.buckets[index];
    for (let entry of bucket) {
      if (entry[0] === key) {
        console.log(`找到键 "${key}" 在索引 ${index}，值为 ${entry[1]}`);
        return entry[1];
      }
    }
    console.log(`键 "${key}" 未找到`);
    return undefined;
  }
}

const map = new ChainedHashMap();
map.set('cat', '小猫');
map.set('act', '行动');  // 与 'cat' 可能冲突
map.set('tac', 'TAC');  // 可能冲突
map.get('cat');
map.get('act');
console.log('桶状态:', map.buckets);

class HashMapWithResize {
  constructor(initialCapacity = 4, loadFactorThreshold = 0.75) {
    this.capacity = initialCapacity;
    this.size = 0;
    this.threshold = loadFactorThreshold;
    this.buckets = new Array(this.capacity).fill(null).map(() => []);
  }
  _hash(key) {
    let hash = 0;
    for (let i = 0; i < key.length; i++) {
      hash = (hash * 31 + key.charCodeAt(i)) | 0;
    }
    return (hash & 0x7fffffff) % this.capacity;
  }
  _resize() {
    const oldBuckets = this.buckets;
    this.capacity *= 2;
    this.buckets = new Array(this.capacity).fill(null).map(() => []);
    this.size = 0;
    console.log(`扩容！新容量: ${this.capacity}`);
    for (let bucket of oldBuckets) {
      for (let [key, value] of bucket) {
        this.set(key, value);
      }
    }
  }
  set(key, value) {
    if (this.size / this.capacity > this.threshold) {
      this._resize();
    }
    const index = this._hash(key);
    const bucket = this.buckets[index];
    for (let entry of bucket) {
      if (entry[0] === key) {
        entry[1] = value;
        return;
      }
    }
    bucket.push([key, value]);
    this.size++;
    console.log(`插入 "${key}" 到索引 ${index}，当前负载因子: ${(this.size/this.capacity).toFixed(2)}`);
  }
  get(key) {
    const index = this._hash(key);
    const bucket = this.buckets[index];
    for (let entry of bucket) {
      if (entry[0] === key) return entry[1];
    }
    return undefined;
  }
}

const map = new HashMapWithResize(4, 0.75);
map.set('a', 1);
map.set('b', 2);
map.set('c', 3);
map.set('d', 4);  // 此时负载因子 4/4=1 > 0.75，触发扩容
map.set('e', 5);
console.log('最终大小:', map.size, '容量:', map.capacity);
